TOPICS = {
 "DBMS Fundamentals":{"title":"DBMS Fundamentals","content":"A **Database Management System (DBMS)** is software used to define, create, store, retrieve and manage data. It provides controlled access to data while supporting integrity, security and concurrent users.","points":["A database is an organized collection of related data.","A DBMS provides data definition, manipulation, security and recovery.","Examples include PostgreSQL, MySQL, SQLite and Oracle Database."],"sql":""},
 "Keys and Constraints":{"title":"Keys and Constraints","content":"A **primary key** uniquely identifies each row and cannot be NULL. A **foreign key** references a candidate key in another table and helps maintain referential integrity.","points":["Primary keys must be unique and non-null.","Foreign keys model relationships between tables.","UNIQUE, NOT NULL, CHECK and DEFAULT are common constraints."],"sql":"CREATE TABLE Enrollments (\n  student_id INT,\n  course_id INT,\n  PRIMARY KEY (student_id, course_id),\n  FOREIGN KEY (student_id) REFERENCES Students(id)\n);"},
 "Normalization":{"title":"Database Normalization","content":"Normalization organizes relational tables to reduce redundancy and avoid update anomalies. 1NF requires atomic values; 2NF removes partial dependency on a candidate key; 3NF removes transitive dependency of non-key attributes.","points":["1NF: atomic column values and no repeating groups.","2NF: 1NF plus no partial dependency on a candidate key.","3NF: 2NF plus no transitive dependency of non-key attributes.","BCNF: every determinant is a candidate key."],"sql":""},
 "ACID Properties":{"title":"ACID Properties","content":"ACID describes the key properties of reliable transactions: **Atomicity**, **Consistency**, **Isolation** and **Durability**.","points":["Atomicity: all transaction operations succeed or none do.","Consistency: constraints remain satisfied.","Isolation: concurrent transactions behave safely.","Durability: committed changes survive failures."],"sql":"BEGIN;\nUPDATE accounts SET balance = balance - 500 WHERE id = 1;\nUPDATE accounts SET balance = balance + 500 WHERE id = 2;\nCOMMIT;"},
 "SQL Joins":{"title":"SQL Joins","content":"Joins combine rows from related tables. INNER JOIN returns matching rows; LEFT JOIN preserves every row from the left table; RIGHT JOIN preserves rows from the right; FULL OUTER JOIN preserves rows from both sides.","points":["Use explicit ON conditions to make relationships clear.","INNER JOIN excludes unmatched rows.","LEFT JOIN is useful for finding missing related records."],"sql":"SELECT s.name, e.course_id\nFROM students AS s\nINNER JOIN enrollments AS e ON e.student_id = s.id;"},
 "Indexes":{"title":"Database Indexes","content":"An index is an auxiliary data structure that helps the database locate rows more efficiently. Indexes can speed up reads but consume storage and add work to INSERT, UPDATE and DELETE operations.","points":["B-tree indexes are common for equality and range lookups.","Index columns frequently used in filters and joins.","Avoid adding indexes without measuring query workload."],"sql":"CREATE INDEX idx_students_email ON students(email);"}
}
