 {"question":"Which key uniquely identifies each row in a table?","options":["Foreign key","Primary key","Composite attribute","Index only"],"answer":"Primary key","explanation":"A primary key uniquely identifies each row and cannot contain NULL values."},
 {"question":"Which ACID property means committed data survives a crash?","options":["Atomicity","Isolation","Durability","Consistency"],"answer":"Durability","explanation":"Durability ensures committed changes persist after failures."},
 {"question":"Which normal form removes partial dependencies?","options":["1NF","2NF","3NF","BCNF"],"answer":"2NF","explanation":"Second Normal Form removes partial dependencies on candidate keys."},
 {"question":"Which JOIN keeps every row from the left table?","options":["INNER JOIN","CROSS JOIN","LEFT JOIN","SELF JOIN"],"answer":"LEFT JOIN","explanation":"LEFT JOIN preserves all left-side rows, filling unmatched right-side columns with NULL."},
 {"question":"What does SQL stand for?","options":["Structured Query Language","Simple Question Logic","System Query Link","Structured Queue Language"],"answer":"Structured Query Language","explanation":"SQL is the standard language used to work with relational databases."}
